/* Monthly club and customer self-service, entirely local demonstration. */
let clubStep=1,clubDraft={profile:'Cristã',finish:'Marfim',payment:'card',name:'',email:'',phone:'',street:'',number:'',extra:'',district:'',city:'',state:'SP',cep:'',consent:false},lastClubId=null;
function clubLandingPage(){return `<main id="main" class="club-page"><section class="container club-hero"><div class="club-hero-copy"><h1>Uma cesta de fé.<br><em>Uma surpresa por mês.</em></h1><p>Conheça o <strong>${esc(ops.settings.clubName)}</strong>: uma seleção de peças cristãs em 3D, uma mensagem de oração e um novo motivo para cultivar a fé em casa.</p><div class="club-price"><strong>${money(ops.settings.price)}</strong><span>/ mês<br><small>frete incluído no plano de demonstração</small></span></div><a class="btn" href="#/clube/assinar">Quero fazer parte ${icon('heart')}</a><small>Plano único · renovação mensal simulada · pausa e cancelamento na sua conta</small></div><div class="club-hero-image"><img src="assets/club-basket.png" alt="Cesta conceitual com peças cristãs em 3D, mensagem de oração e embalagem de presente"><span>Imagem conceitual · itens variam conforme a edição.</span></div></section><div class="club-ribbon"><div class="container"><span>${icon('box')}Uma nova edição por mês</span><span>${icon('cross')}Alinhada à sua caminhada</span><span>${icon('truck')}Entrega no seu endereço</span><span>${icon('user')}Você acompanha tudo na conta</span></div></div><section class="container club-section"><h2>Uma assinatura.<br><em>Muitos pequenos encontros com Deus.</em></h2><div class="club-how"><div><span>${icon('heart')}</span><h3>Escolha sua caminhada.</h3><p>Cesta católica, evangélica ou cristã, com referências que fazem sentido para você.</p></div><div><span>${icon('gift')}</span><h3>Receba uma nova edição.</h3><p>Peças 3D selecionadas, uma mensagem de fé e uma embalagem preparada para acolher.</p></div><div><span>${icon('box')}</span><h3>Cultive a fé na rotina.</h3><p>Acompanhe cada envio e cada cobrança. Pause ou cancele a simulação quando quiser.</p></div></div></section><section class="container club-edition"><div class="club-edition-art">${photo(0,'','Cruz Essencial, exemplo da seleção mensal')}${photo(2,'','Espírito Santo, exemplo da seleção mensal')}</div><div><h2>${esc(ops.settings.edition)}.</h2><p>A edição de ${opMonth(ops.settings.editionMonth+'-08')} reúne símbolos de paz e esperança. A seleção acompanha o perfil escolhido na assinatura.</p><ul><li>Peças religiosas impressas em 3D</li><li>Mensagem de oração e cartão da edição</li><li>Embalagem para guardar ou presentear</li><li>Frete incluído no valor mensal demonstrativo</li></ul><a href="#/clube/assinar" class="btn secondary">Escolher minha cesta ${icon('arrow')}</a></div></section><section class="container club-section"><div class="club-plan"><div><h2>Um valor só.<br><em>Todo mês, uma nova cesta.</em></h2><p>Você conhece o valor antes de começar e encontra o controle da assinatura na sua conta.</p><div class="details-list"><details><summary>Quando a cesta é enviada?</summary><p>A expedição mensal de demonstração está prevista para o dia ${ops.settings.dispatchDay}. O acompanhamento aparece em Minha conta → Envios do clube.</p></details><details><summary>Como funciona o pagamento?</summary><p>Cartão de teste com renovação simulada ou Pix mensal, que precisa ser confirmado a cada ciclo. Não usamos dados reais de cartão e nenhum valor é cobrado.</p></details><details><summary>Posso pausar, pular uma edição ou cancelar?</summary><p>Sim. As ações ficam na área da assinatura. Uma cesta já paga mantém seu histórico de envio; a pausa ou o cancelamento interrompem as próximas renovações desta simulação.</p></details></div></div><aside><span class="badge olive">Plano mensal único</span><h3>${esc(ops.settings.clubName)}</h3><div class="club-plan-price">${money(ops.settings.price)}<small>/ mês</small></div><p>Frete incluído · seleção conforme seu perfil</p><a href="#/clube/assinar" class="btn full">Começar minha assinatura ${icon('arrow')}</a><small>Preço, composição e condições ilustrativos e editáveis no painel administrador.</small></aside></div></section></main>`}
function clubSummary(){return `<aside class="summary club-summary"><img src="assets/club-basket.png" alt="Cesta mensal conceitual"><h2>${esc(ops.settings.clubName)}</h2><div class="money-line"><span>Periodicidade</span><strong>Mensal</strong></div><div class="money-line"><span>Seu perfil</span><span>${esc(clubDraft.profile)}</span></div><div class="money-line"><span>Frete</span><span>Incluído</span></div><div class="money-line total"><span>Por mês</span><strong>${money(ops.settings.price)}</strong></div><small>Renovação de demonstração. Nenhuma cobrança ou entrega real será realizada.</small><a href="#/clube" class="text-btn">Ver o plano</a></aside>`}
function subscriptionCheckoutPage(){const existing=opCurrentSub();if(existing&&existing.status!=='Cancelada')return `<main id="main" class="container"><div class="empty">${icon('box')}<h1 style="font-size:2.2rem">Você já faz parte deste cantinho.</h1><p>Sua assinatura está ${existing.status.toLowerCase()}. Gerencie seus próximos passos na sua conta.</p><a class="btn" href="#/conta/assinatura">Ver minha assinatura ${icon('arrow')}</a></div></main>`;return `<main id="main" class="container"><div class="checkout-layout club-checkout"><section><a class="arrow-link" href="#/clube">Voltar ao clube</a><h1>Sua próxima surpresa começa aqui.</h1><div class="steps">${['Sua cesta','Seus dados','Assinatura'].map((x,i)=>`<span class="${clubStep===i+1?'active':clubStep>i+1?'done':''}"><b>${clubStep>i+1?'✓':i+1}</b>${x}</span>`).join('')}</div><div class="notice" style="margin-top:24px">Assinatura de demonstração. Use dados fictícios; nenhuma renovação real será criada.</div><form id="club-checkout-form" class="stack" style="margin-top:26px">${clubStep===1?`<h2 style="font-size:1.3rem">Qual caminho acolhe a sua fé?</h2>${[['Católica','Imagens sacras e símbolos de devoção.'],['Evangélica','A Palavra, a cruz e lembretes da caminhada cristã.'],['Cristã','Símbolos de paz, amor e esperança em Cristo.']].map(([p,t])=>`<label class="radio-card ${clubDraft.profile===p?'active':''}"><input type="radio" name="profile" value="${p}" ${clubDraft.profile===p?'checked':''}><span class="grow"><strong>Cesta ${p.toLowerCase()}</strong><small>${t}</small></span></label>`).join('')}<label>Preferência de acabamento<select name="finish">${['Marfim','Terracota','Surpresa'].map(c=>`<option ${clubDraft.finish===c?'selected':''}>${c}</option>`).join('')}</select></label><p class="muted" style="font-size:.78rem">A curadoria de cada mês é uma surpresa dentro do perfil escolhido. Imagens e composições são conceituais.</p>`:clubStep===2?`<button type="button" class="text-btn" data-op="club-fill-demo">Preencher com dados fictícios</button><div class="form-grid"><label class="span2">Nome completo<input name="name" required minlength="3" value="${esc(clubDraft.name)}" autocomplete="off"></label><label class="span2">E-mail de demonstração<input name="email" type="email" required value="${esc(clubDraft.email)}" autocomplete="off"></label><label>Telefone fictício<input name="phone" required minlength="10" value="${esc(clubDraft.phone)}"></label><label>CEP<input name="cep" pattern="[0-9]{5}-?[0-9]{3}" required maxlength="9" placeholder="00000-000" value="${esc(clubDraft.cep)}"></label><label class="span2">Rua ou avenida<input name="street" required value="${esc(clubDraft.street)}"></label><label>Número<input name="number" required value="${esc(clubDraft.number)}"></label><label>Complemento<input name="extra" value="${esc(clubDraft.extra)}"></label><label>Bairro<input name="district" required value="${esc(clubDraft.district)}"></label><label>Cidade<input name="city" required value="${esc(clubDraft.city)}"></label><label>Estado<select name="state">${['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'].map(c=>`<option ${clubDraft.state===c?'selected':''}>${c}</option>`).join('')}</select></label></div>`:`<h2 style="font-size:1.35rem">Como você prefere renovar?</h2>${[['card','Cartão de teste','Renovação mensal automática simulada. Sem informar dados reais de cartão.'],['pix','Pix mensal','A cada mês, confirme um novo pagamento Pix de demonstração.']].map(([id,t,d])=>`<label class="radio-card ${clubDraft.payment===id?'active':''}"><input type="radio" name="clubPayment" value="${id}" ${clubDraft.payment===id?'checked':''}><span class="grow"><strong>${t}</strong><small>${d}</small></span>${icon(id==='card'?'card':'pix')}</label>`).join('')}<div class="demo-card">${icon(clubDraft.payment==='card'?'card':'pix')}<div><strong>${clubDraft.payment==='card'?'Cartão de demonstração ···· 4242':'Pix mensal de demonstração'}</strong><small>${money(ops.settings.price)} por ciclo mensal, com frete incluído.</small></div></div><label class="check-line"><input name="clubConsent" type="checkbox" required ${clubDraft.consent?'checked':''}>Entendi que este plano é mensal, com renovação simulada de ${money(ops.settings.price)}, e posso pausar ou cancelar na minha conta.</label>`}<div class="form-actions">${clubStep>1?'<button type="button" class="text-btn" data-op="club-back">Voltar</button>':'<span></span>'}<button class="btn">${clubStep===3?'Confirmar assinatura de demonstração':'Continuar'} ${icon('arrow')}</button></div></form></section>${clubSummary()}</div></main>`}
function enrollClub(){const sameEmail=existingClubForEmail(clubDraft.email);if(sameEmail){const c=opClient(sameEmail.customerId);customer={...(customer||{}),name:c.name,email:c.email,clubCustomerId:c.id};persist('customer',customer);navigate('#/conta/assinatura');toast('Este e-mail já possui uma assinatura de demonstração.');return}if(opCurrentSub()&&opCurrentSub().status!=='Cancelada'){navigate('#/conta/assinatura');return}let c=ops.clients.find(x=>x.email.toLowerCase()===clubDraft.email.toLowerCase());const address=Object.fromEntries(['name','email','phone','street','number','extra','district','city','state','cep'].map(k=>[k,clubDraft[k]]));if(!c){c={id:opId('CLI'),...address,status:'Ativo',created:OPS_DAY,notes:'Assinante criado pelo fluxo local.'};ops.clients.push(c)}else Object.assign(c,address);customer={...(customer||{}),name:c.name,email:c.email,clubCustomerId:c.id};persist('customer',customer);const sid=opId('ASS'),oid=opId('PED'),cid=opId('COB'),paid=clubDraft.payment==='card';const s={id:sid,customerId:c.id,profile:clubDraft.profile,finish:clubDraft.finish,price:ops.settings.price,status:paid?'Ativa':'Pagamento pendente',payment:clubDraft.payment,created:OPS_DAY,nextRenewal:opAddMonth(OPS_DAY),nextShipment:OPS_DAY.slice(0,8)+String(ops.settings.dispatchDay).padStart(2,'0'),address,history:[{date:OPS_DAY,label:'Assinatura criada no protótipo.'}]};ops.subscriptions.unshift(s);ops.orders.unshift({id:oid,customerId:c.id,subscriptionId:sid,type:'Clube',edition:opMonth(OPS_DAY)+' · '+ops.settings.edition,profile:s.profile,items:clubItems(s.profile,s.finish),total:s.price,shipping:0,status:paid?'Confirmado':'Aguardando pagamento',created:OPS_DAY,due:s.nextShipment,address:{...address},chargeId:cid,tracking:'',carrier:'Correios (simulação)',priority:'Normal',notes:'Primeira edição da assinatura.'});ops.charges.unshift({id:cid,customerId:c.id,subscriptionId:sid,orderId:oid,amount:s.price,method:s.payment,status:paid?'Pago':'Pendente',due:OPS_DAY,paidAt:paid?OPS_DAY:null,description:'Primeira edição do clube',cycle:OPS_DAY.slice(0,7)});if(paid)productionOps(oid);lastClubId=sid;auditOps('Nova assinatura pelo site',sid,location.hash.startsWith('#/admin')?'Administrador demo':'Cliente demo');navigate('#/clube/confirmacao')}
function clubSuccessPage(){const s=opSubscription(lastClubId)||opCurrentSub();if(!s)return clubLandingPage();const pending=s.status==='Pagamento pendente',charge=ops.charges.find(c=>c.subscriptionId===s.id&&c.status==='Pendente');return `<main id="main" class="container"><section class="success"><div class="success-icon">${icon(pending?'pix':'heart')}</div><h1>${pending?'Seu lugar está reservado.':'Bem-vindo ao nosso clube de fé.'}</h1><p>${pending?'Falta confirmar o Pix de demonstração para preparar a primeira cesta.':'Sua primeira cesta já aparece na sua conta. Acompanhe a preparação e cada novo envio.'}</p><div class="success-panel"><div class="row between"><h2>${esc(ops.settings.clubName)}</h2>${opStatus(s.status)}</div><div class="money-line" style="margin-top:23px"><span>Valor mensal · frete incluído</span><strong>${money(s.price)}</strong></div><p class="muted" style="font-size:.83rem">Perfil ${esc(s.profile.toLowerCase())} · próxima renovação ${opDate(s.nextRenewal)}</p><p class="muted" style="font-size:.78rem;margin-top:10px">Nenhum pagamento ou envio real foi criado.</p>${pending&&charge?`<button class="btn full" style="margin-top:20px" data-op="pay-club" data-id="${charge.id}">Simular pagamento do Pix ${icon('check')}</button>`:''}</div><div class="row wrap" style="justify-content:center;margin-top:26px"><a href="#/conta/assinatura" class="btn">Acompanhar minha assinatura ${icon('arrow')}</a><a href="#/conta/envios" class="btn secondary">Ver meus envios</a></div></section></main>`}
function subscriptionTabs(tab){return `<nav class="subscription-tabs" aria-label="Área do assinante">${[['assinatura','Minha assinatura'],['envios','Meus envios'],['cobrancas','Cobranças'],['atendimentos','Atendimentos']].map(([id,t])=>`<a href="#/conta/${id}" class="${id===tab?'active':''}">${t}</a>`).join('')}</nav>`}
function accountClubContent(tab){const c=opCurrentClient(),s=opCurrentSub();if(tab==='atendimentos')return clientTicketsPage(c);if(!s)return `<h1>Um novo encontro com a fé.</h1><p>Você ainda não tem uma assinatura de demonstração.</p><div class="account-club-empty"><img src="assets/club-basket.png" alt="Cesta conceitual do clube"><div><h2>${esc(ops.settings.clubName)}</h2><p>Uma seleção de peças cristãs todo mês, por ${money(ops.settings.price)}, com frete incluído no plano demonstrativo.</p><a class="btn" href="#/clube">Conhecer o clube ${icon('arrow')}</a></div></div>`;const shipments=ops.orders.filter(o=>o.subscriptionId===s.id).sort((a,b)=>b.created.localeCompare(a.created));const charges=ops.charges.filter(x=>x.subscriptionId===s.id).sort((a,b)=>b.due.localeCompare(a.due));return `${subscriptionTabs(tab)}${tab==='envios'?`<h1>Uma nova cesta, a cada capítulo.</h1><p>Acompanhe o caminho de cada edição até sua casa.</p><div class="shipment-list">${shipments.map(shipmentCard).join('')}</div>`:tab==='cobrancas'?`<h1>Suas cobranças, com clareza.</h1><p>Mensalidade contratada: ${money(s.price)}. Nenhuma cobrança real será feita.</p><div class="client-billing-list">${charges.map(x=>`<article><div><h3>${esc(x.description)}</h3><p>${opDate(x.due)} · ${x.method==='card'?'Cartão de teste':'Pix mensal'}</p></div><strong>${money(x.amount)}</strong>${opStatus(x.status)}${['Pendente','Recusado'].includes(x.status)?`<button class="btn secondary small" data-op="pay-club" data-id="${x.id}">Simular pagamento</button>`:`<button class="text-btn" data-op="receipt" data-id="${x.id}">Ver comprovante</button>`}</article>`).join('')}</div>`:`<h1>Sua fé tem um lugar aqui.</h1><p>Gerencie sua cesta mensal e acompanhe seus próximos momentos.</p><div class="subscription-main"><div class="subscription-cover"><img src="assets/club-basket.png" alt="Cesta mensal conceitual"></div><div><div class="row between wrap"><h2>${esc(ops.settings.clubName)}</h2>${opStatus(s.status)}</div><div class="subscription-value">${money(s.price)}<small>/ mês · frete incluído</small></div><dl class="subscription-facts"><div><dt>Perfil</dt><dd>Cesta ${esc(s.profile.toLowerCase())}</dd></div><div><dt>Renovação</dt><dd>${['Pausada','Cancelada'].includes(s.status)?'Interrompida':opDate(s.nextRenewal)}</dd></div><div><dt>Pagamento</dt><dd>${s.payment==='card'?'Cartão de teste ···· 4242':'Pix mensal'}</dd></div><div><dt>Próxima expedição</dt><dd>${nextClubShipment(s)}</dd></div></dl></div></div>${s.status==='Pagamento pendente'?'<div class="notice warn">Há uma cobrança aguardando confirmação. Você pode simular o pagamento na aba Cobranças.</div>':''}<div class="subscriber-actions"><button class="btn secondary small" data-op="edit-subscription" data-id="${s.id}">Preferências e endereço</button>${s.status==='Pausada'?`<button class="btn small" data-op="sub-state" data-state="Ativa" data-id="${s.id}">Retomar assinatura</button>`:s.status==='Ativa'?`<button class="btn secondary small" data-op="sub-skip" data-id="${s.id}">Pular próxima edição</button><button class="btn secondary small" data-op="sub-state" data-state="Pausada" data-id="${s.id}">Pausar assinatura</button>`:''}${s.status!=='Cancelada'?`<button class="text-btn danger-text" data-op="cancel-subscription" data-id="${s.id}">Cancelar assinatura</button>`:`<a class="btn small" href="#/clube/assinar">Criar nova assinatura</a>`}</div><div class="subscriber-address"><h3>Seu endereço de entrega</h3><p>${esc(s.address.street)}, ${esc(s.address.number)} ${esc(s.address.extra||'')} · ${esc(s.address.city)}/${esc(s.address.state)} · CEP ${esc(s.address.cep)}</p><small>Uma alteração vale para os próximos envios ainda não despachados.</small></div><div class="section-header" style="margin-top:32px"><h2 style="font-size:1.35rem">Sua próxima cesta</h2><a href="#/conta/envios" class="arrow-link">Ver todos os envios ${icon('arrow')}</a></div>${shipments[0]?shipmentCard(shipments[0]):''}<details class="subscription-history"><summary>Histórico da assinatura</summary>${s.history.map(h=>`<p><small>${opDate(h.date)}</small> ${esc(h.label)}</p>`).join('')}</details>`}`}
function shipmentCard(o){const steps=['Pagamento confirmado','Em produção','Enviado','Entregue'],index=o.status==='Entregue'?3:o.status==='Enviado'?2:['Em produção','Em acabamento','Pronto para envio'].includes(o.status)?1:o.status==='Aguardando pagamento'?-1:0;return `<article class="shipment-card"><div class="row between wrap"><div><h3>${esc(o.edition||o.id)}</h3><p>${esc(o.id)} · expedição prevista ${opDate(o.due)}</p></div>${opStatus(o.status)}</div><div class="order-preview">${o.items.map(x=>photo(x.img,'',x.name)).join('')}</div><ol class="shipment-progress">${steps.map((t,i)=>`<li class="${i<=index?'done':''}"><span>${i<=index?icon('check'):''}</span>${t}</li>`).join('')}</ol><div class="row between wrap"><small class="muted">${o.tracking?'Rastreio de demonstração: '+esc(o.tracking):'Código de rastreio disponível após a expedição simulada.'}</small><button class="text-btn" data-op="track-order" data-id="${o.id}">Detalhes do envio ${icon('arrow')}</button></div></article>`}
function clientTicketsPage(c){const list=c?ops.tickets.filter(t=>t.customerId===c.id):[];return `${subscriptionTabs('atendimentos')}<h1>Estamos aqui para acolher.</h1><p>Acompanhe seus atendimentos de demonstração e envie novas mensagens locais.</p><button class="btn" data-op="new-client-ticket">Abrir atendimento ${icon('chat')}</button><div class="client-ticket-list">${list.length?list.map(t=>`<article><div class="row between"><h3>${esc(t.subject)}</h3>${opStatus(t.status)}</div><small>${t.id} · ${opDate(t.created)}</small><div class="ticket-thread">${t.messages.map(m=>`<div class="ticket-message ${m.by==='equipe'?'staff':''}"><strong>${m.by==='equipe'?'Equipe Mãos em Oração':'Você'}</strong><p>${esc(m.text)}</p></div>`).join('')}</div><form class="row" data-form="client-reply" data-id="${t.id}"><input name="message" required minlength="3" placeholder="Escreva sua mensagem fictícia" aria-label="Mensagem para ${esc(t.subject)}"><button class="btn small">Enviar na demonstração</button></form></article>`).join(''):'<div class="empty"><p>Nenhum atendimento por aqui. Você pode abrir o primeiro quando precisar.</p></div>'}</div>`}
function refreshClubFeatures(){const admin=location.hash.startsWith('#/admin');document.body.classList.toggle('admin-mode',admin);if(admin)return;const nav=$('.nav-links');if(nav&&!$('.club-nav',nav))nav.insertAdjacentHTML('beforeend',`<a class="club-nav" href="#/clube">${icon('gift')}Clube mensal</a>`);const side=$('.account-side');if(side&&!$('.club-account-link',side))side.insertAdjacentHTML('beforeend',`<a class="club-account-link ${location.hash==='#/conta/assinatura'?'active':''}" href="#/conta/assinatura">${icon('gift')}Minha assinatura</a><a href="#/conta/envios">${icon('truck')}Envios do clube</a><a href="#/conta/atendimentos">${icon('chat')}Atendimentos</a>`);const foot=$('.footer-grid>div:last-child');if(foot&&!$('.admin-demo-link',foot))foot.insertAdjacentHTML('beforeend',`<a href="#/clube">Clube Cesta com Jesus</a><a class="admin-demo-link" href="#/admin">Painel administrador · demo</a>`);const home=$('.faith-home .faith-collections');if(home&&!$('.home-club-banner'))home.insertAdjacentHTML('afterend',`<section class="container home-club-banner"><div><h2>Todo mês, uma nova cesta.<br><em>O mesmo amor por Cristo.</em></h2><p>${esc(ops.settings.clubName)} · ${money(ops.settings.price)}/mês com frete incluído no plano demonstrativo.</p><a class="btn light" href="#/clube">Conhecer o clube ${icon('arrow')}</a></div><img src="assets/club-basket.png" alt="Cesta mensal de peças cristãs em 3D, imagem conceitual"></section>`)}
function clubDialog(html,label='Gerenciar assinatura'){openFeatureDialog(`<div class="viewer-header"><h2>${esc(label)}</h2><button class="icon-btn" data-action="close" aria-label="Fechar ${esc(label)}">${icon('close')}</button></div><div class="op-dialog-body">${html}</div>`,'op-dialog',label)}
function editSubscriptionDialog(s){clubDialog(`<form data-form="edit-subscription" data-id="${s.id}" class="form-grid"><label>Perfil<select name="profile">${['Católica','Evangélica','Cristã'].map(x=>`<option ${s.profile===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Acabamento<select name="finish">${['Marfim','Terracota','Surpresa'].map(x=>`<option ${s.finish===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="span2">Pagamento dos próximos ciclos<select name="payment"><option value="card" ${s.payment==='card'?'selected':''}>Cartão de teste · renovação automática simulada</option><option value="pix" ${s.payment==='pix'?'selected':''}>Pix mensal · confirmação a cada ciclo</option></select></label>${[['street','Rua'],['number','Número'],['city','Cidade'],['state','Estado'],['cep','CEP']].map(([k,t])=>`<label>${t}<input name="${k}" required value="${esc(s.address[k]||'')}"></label>`).join('')}<div class="notice span2">Alterações valem para envios ainda não despachados. A mensalidade contratada permanece ${money(s.price)}.</div><button class="btn span2">Salvar preferências de demonstração</button></form>`,'Preferências da assinatura')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-op]');if(!b)return;const a=b.dataset.op,id=b.dataset.id,s=opSubscription(id);
  if(a==='club-back'){clubStep=Math.max(1,clubStep-1);render();window.scrollTo(0,0)}
  if(a==='club-fill-demo'){const f=$('#club-checkout-form'),d={name:'Cliente do Clube',email:'clube.teste@exemplo.com',phone:'11999990000',street:'Rua Exemplo',number:'123',extra:'Apto 42',district:'Centro',city:'São Paulo',state:'SP',cep:'01001-000'};Object.assign(clubDraft,d);Object.entries(d).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v});toast('Dados fictícios preenchidos.')}
  if(a==='pay-club'){payChargeOps(id);const charge=ops.charges.find(x=>x.id===id);if(charge?.orderId&&opOrder(charge.orderId)?.type==='Clube')productionOps(charge.orderId);render();toast('Pagamento confirmado na simulação.')}
  if(a==='edit-subscription'&&s)editSubscriptionDialog(s);
  if(a==='sub-state'&&s){s.status=b.dataset.state;s.history.unshift({date:OPS_DAY,label:s.status==='Pausada'?'Pausa solicitada para os próximos ciclos.':'Assinatura retomada na demonstração.'});auditOps('Assinatura '+s.status.toLowerCase(),s.id,location.hash.startsWith('#/admin')?'Administrador demo':'Cliente demo');render();toast(s.status==='Pausada'?'Próximas renovações pausadas.':'Assinatura retomada.')}
  if(a==='sub-skip'&&s){s.nextRenewal=opAddMonth(s.nextRenewal);s.nextShipment=opAddMonth(s.nextShipment);s.history.unshift({date:OPS_DAY,label:'Próxima edição pulada; novas datas atualizadas.'});auditOps('Edição pulada',s.id,location.hash.startsWith('#/admin')?'Administrador demo':'Cliente demo');render();toast('A próxima renovação foi adiada em um mês.')}
  if(a==='cancel-subscription'&&s)clubDialog(`<p>As próximas renovações serão interrompidas. Cestas já pagas continuam no histórico de envio.</p><form data-form="cancel-subscription" data-id="${s.id}" class="stack" style="margin-top:23px"><label>Motivo <span class="muted">(opcional)</span><select name="reason"><option>Prefiro não informar</option><option>Quero fazer uma pausa maior</option><option>O valor não cabe neste momento</option><option>Outro motivo</option></select></label><button class="btn danger">Confirmar cancelamento de demonstração</button><button type="button" class="btn secondary" data-action="close">Manter minha assinatura</button></form>`,'Cancelar assinatura');
  if(a==='track-order'){const o=opOrder(id);if(o)clubDialog(`${shipmentCard(o)}<div class="subscriber-address"><h3>Destino</h3><p>${esc(o.address.street)}, ${esc(o.address.number)} · ${esc(o.address.city)}/${esc(o.address.state)}</p><small>${esc(o.carrier||'Transportadora a definir')} · acompanhamento demonstrativo, sem remessa real.</small></div>`,'Detalhes do envio')}
  if(a==='receipt'){const c=ops.charges.find(x=>x.id===id);if(c)clubDialog(`<div class="receipt-demo"><h3>Comprovante da simulação</h3><p>${c.id}</p><div class="money-line"><span>Valor</span><strong>${money(c.amount)}</strong></div><div class="money-line"><span>Situação</span>${opStatus(c.status)}</div><p>${esc(c.description)} · ${opDate(c.paidAt||c.due)}</p><small>Documento ilustrativo, sem validade fiscal ou financeira.</small></div>`,'Comprovante demonstrativo')}
  if(a==='new-client-ticket')clubDialog(`<form data-form="new-client-ticket" class="stack"><label>Assunto<input name="subject" required minlength="5" maxlength="100"></label><label>Categoria<select name="category"><option>Assinatura</option><option>Entrega</option><option>Pagamento</option><option>Produto</option></select></label><label>Sua mensagem fictícia<textarea name="message" required minlength="10" maxlength="800"></textarea></label><div class="notice">Atendimento salvo apenas na demonstração local; nenhuma mensagem é enviada.</div><button class="btn">Abrir atendimento na demonstração</button></form>`,'Abrir atendimento');
});
document.addEventListener('input',e=>{if(e.target.form?.id==='club-checkout-form'){const t=e.target;if(t.name==='clubConsent')clubDraft.consent=t.checked;else if(t.name==='clubPayment')clubDraft.payment=t.value;else if(t.name)clubDraft[t.name]=t.value}});
document.addEventListener('change',e=>{if(e.target.form?.id==='club-checkout-form'){const t=e.target;if(t.name==='clubPayment')clubDraft.payment=t.value;else if(t.name==='clubConsent')clubDraft.consent=t.checked;else clubDraft[t.name]=t.value;if(['profile','finish','clubPayment'].includes(t.name))render()}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='club-checkout-form'){e.preventDefault();const d=Object.fromEntries(new FormData(f));Object.assign(clubDraft,d);if(clubStep<3){clubStep++;render();window.scrollTo(0,0)}else if(f.reportValidity())enrollClub();return}const type=f.dataset.form;if(!['edit-subscription','cancel-subscription','new-client-ticket','client-reply'].includes(type))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));if(type==='edit-subscription'){const s=opSubscription(f.dataset.id);Object.assign(s,{profile:d.profile,finish:d.finish,payment:d.payment});for(const k of ['street','number','city','state','cep'])s.address[k]=d[k];for(const o of ops.orders.filter(x=>x.subscriptionId===s.id&&!['Enviado','Entregue','Cancelado'].includes(x.status)))o.address={...s.address};s.history.unshift({date:OPS_DAY,label:'Preferências e endereço atualizados.'});auditOps('Preferências alteradas',s.id,location.hash.startsWith('#/admin')?'Administrador demo':'Cliente demo');closeOverlay();render();toast('Preferências salvas na demonstração.')}if(type==='cancel-subscription'){const s=opSubscription(f.dataset.id);s.status='Cancelada';s.history.unshift({date:OPS_DAY,label:'Cancelamento: '+d.reason});auditOps('Assinatura cancelada',s.id,location.hash.startsWith('#/admin')?'Administrador demo':'Cliente demo');closeOverlay();render();toast('Renovações futuras interrompidas na simulação.')}if(type==='new-client-ticket'){const c=opCurrentClient();if(!c){toast('Entre na conta de demonstração para abrir um atendimento.');return}ops.tickets.unshift({id:opId('AT'),customerId:c.id,subject:d.subject,category:d.category,status:'Aberto',priority:'Normal',assignee:'Camila',created:OPS_DAY,messages:[{by:'cliente',text:d.message,date:OPS_DAY}]});auditOps('Atendimento aberto',c.id,location.hash.startsWith('#/admin')?'Administrador demo':'Cliente demo');closeOverlay();navigate('#/conta/atendimentos');render()}if(type==='client-reply'){const t=ops.tickets.find(x=>x.id===f.dataset.id);t.messages.push({by:'cliente',text:d.message,date:OPS_DAY});t.status='Aberto';saveOps();render();toast('Mensagem salva no atendimento local.')}});
